<script setup lang="ts">
import {AlignCenter, AlignHorizontalSpaceAround, ChevronDown, ChevronUp, Eye, Trash2} from 'lucide-vue-next';
import type {CostumeEntry} from '../model/canvas-types';
const props=defineProps<{entries:CostumeEntry[];previewId?:string|null}>();
const emit=defineEmits<{rename:[id:string,name:string];remove:[id:string];move:[id:string,direction:-1|1];align:[mode:'center'|'bottom-center'];pivot:[id:string,x:number,y:number];scale:[id:string,value:number];preview:[id:string]}>();
const numberValue=(event:Event)=>(event.target as HTMLInputElement).valueAsNumber;
</script>
<template><section class="resource-panel"><div class="costume-align"><button type="button" @click="emit('align','center')"><AlignCenter :size="15"/>居中统一</button><button type="button" @click="emit('align','bottom-center')"><AlignHorizontalSpaceAround :size="15"/>底部统一</button></div><div class="costume-list"><article v-for="(entry,index) in props.entries" :key="entry.id" class="costume-item"><div class="costume-row"><span class="costume-row__index">{{index+1}}</span><input :value="entry.name" aria-label="造型名称" @change="emit('rename',entry.id,($event.target as HTMLInputElement).value)"/><span>{{Math.round(entry.frameRect.width)}}×{{Math.round(entry.frameRect.height)}}</span><button title="上移" aria-label="上移造型" :disabled="index===0" @click="emit('move',entry.id,-1)"><ChevronUp :size="14"/></button><button title="下移" aria-label="下移造型" :disabled="index===props.entries.length-1" @click="emit('move',entry.id,1)"><ChevronDown :size="14"/></button><button :class="{'is-marked':props.previewId===entry.id}" title="预览造型" aria-label="预览造型" @click="emit('preview',entry.id)"><Eye :size="14"/></button><button title="移出队列" aria-label="移出造型队列" @click="emit('remove',entry.id)"><Trash2 :size="14"/></button></div><div class="costume-metadata"><label>中心 X<input type="number" step="0.5" :value="entry.pivot.x-entry.frameRect.x" :aria-label="entry.name+'旋转中心 X'" @change="emit('pivot',entry.id,numberValue($event)+entry.frameRect.x,entry.pivot.y)"/></label><label>中心 Y<input type="number" step="0.5" :value="entry.pivot.y-entry.frameRect.y" :aria-label="entry.name+'旋转中心 Y'" @change="emit('pivot',entry.id,entry.pivot.x,numberValue($event)+entry.frameRect.y)"/></label><label>比例<input type="number" min="0.05" max="16" step="0.05" :value="entry.exportScale" :aria-label="entry.name+'输出比例'" @change="emit('scale',entry.id,numberValue($event))"/></label></div></article><p v-if="!props.entries.length" class="resource-empty">框选角色动作并复制为新图层</p></div></section></template>
